$("._tab").click(function () {
    let parentBlock = $(this).parents("._tabs-parent")
    let tabId = $(this).attr("data-tab")
    $(parentBlock).find("._tab").removeClass("_active")
    $(this).addClass("_active")
    $(parentBlock).find(".tab-content").removeClass("_active")
    $(parentBlock).find(`.${tabId}`).addClass("_active")

    // После показа таба — обновить активный swiper
    $(parentBlock).find(`.${tabId} .color-tab-content._active .swiper-container`).each(function() {
        if (this.swiper) this.swiper.update()
    })
})
$(".character-color").click(function () {
    setActiveColor($(this))
})

function setActiveColor(el) {
    let tabContent = $(el).closest(".tab-content")  // ← родной tab-content элемента
    let tabId = $(el).attr("data-color")

    $(el).siblings(".character-color").removeClass("_active")
    $(el).addClass("_active")

    $(tabContent).find(".color-tab-content").removeClass("_active")
    $(tabContent).find(`.${tabId}`).addClass("_active")

    // Пересчитать размеры Swiper после показа
    let activeSlider = $(tabContent).find(`.${tabId} .swiper-container`)[0]
    if (activeSlider && activeSlider.swiper) {
        activeSlider.swiper.update()
    }
}

