let body = document.querySelector("body")
let modalTogglers = document.querySelectorAll("[data-modal]")
let modals = document.querySelectorAll(".modal")

modalTogglers.forEach(el => {
    el.onclick = function () {
        let modalId = el.getAttribute("data-modal")
        openModal(modalId)
    }
})

function closeModals() {
    modals.forEach(modal => {
        modal.classList.remove("_active")
        body.classList.remove("fixed-body2")
    })
}

function openModal(modalId) {
    closeModals()
    let modal = document.querySelector(`#${modalId}`)
    let closeButtons = modal.querySelectorAll(`._close-modal`)

    modal.classList.add("_active")
    body.classList.add("fixed-body2")


    closeButtons.forEach(btn => {
        btn.onclick = () => {
            modal.classList.remove("_active")
            body.classList.remove("fixed-body2")
        }
    })
}

var getScrollBarSize = (function () {
    var el = window.document.createElement('textarea'), style = {
        'visibility': 'hidden', 'position': 'absolute', 'zIndex': '-2147483647',
        'top': '-1000px', 'left': '-1000px', 'width': '1000px', 'height': '1000px',
        'overflow': 'scroll', 'margin': '0', 'border': '0', 'padding': '0'
    }, support = el.clientWidth !== undefined && el.offsetWidth !== undefined;

    for (var key in style) {
        if (style.hasOwnProperty(key)) {
            el.style[key] = style[key];
        }
    }

    return function () {
        var size = null;
        if (support && window.document.body) {
            window.document.body.appendChild(el);
            size = [el.offsetWidth - el.clientWidth, el.offsetHeight - el.clientHeight];
            window.document.body.removeChild(el);
        }

        document.documentElement.style.setProperty('--scrollWidth', `${size[0]}px`);
        return size;
    };
})();

/**
 * Универсальная функция для AJAX-отправки форм
 * @param {string} formId - ID формы
 * @param {string} btnId - ID кнопки отправки
 * @param {string} successModal - ID модального окна при успехе
 * @param {function} [onSuccess] - доп. колбэк при успехе (опционально)
 * @param {function} [onError] - доп. колбэк при ошибке (опционально)
 */
function initAjaxForm(formId, btnId, successModal, onSuccess = null, onError = null) {
    const form = document.getElementById(formId);
    const btn = document.getElementById(btnId);

    if (!form || !btn) return;

    btn.addEventListener('click', async function () {
        const formData = new FormData(form);

        if (!form.reportValidity()) return;  // валидация формы на обязательные поля

        try {
            const response = await fetch(form.dataset.url, {
                method: 'POST',
                body: formData,
                headers: {
                    'X-CSRFToken': formData.get('csrfmiddlewaretoken'),
                }
            });

            const data = await response.json();

            if (data.success) {
                form.reset();
                if (successModal) openModal(successModal);
                if (onSuccess) onSuccess(data);
            } else {
                console.error(data.errors);
                if (onError) onError(data.errors);
            }

        } catch (error) {
            console.error('Ошибка:', error);
            if (onError) onError(error);
        }
    });
}

function initPhoneMask() {
    document.querySelectorAll('input[type="tel"]').forEach(input => {

        function formatPhone(digits) {
            digits = digits.slice(0, 10)

            let result = ''
            if (digits.length === 0) return ''
            result += '+7 ('
            if (digits.length >= 1) result += digits.slice(0, 3)
            if (digits.length >= 4) result += ') ' + digits.slice(3, 6)
            if (digits.length >= 7) result += '-' + digits.slice(6, 8)
            if (digits.length >= 9) result += '-' + digits.slice(8, 10)
            return result
        }

        function getDigits(value) {
            let digits = value.replace(/\D/g, '')
            // Убираем ведущую 7 или 8 только если цифр больше одной
            if (digits.length > 1 && (digits.startsWith('7') || digits.startsWith('8'))) {
                digits = digits.slice(1)
            }
            return digits
        }

        input.addEventListener('input', function () {
            const digits = getDigits(this.value)
            this.value = formatPhone(digits)
        })

        input.addEventListener('keydown', function (e) {
            if (e.key === 'Backspace') {
                e.preventDefault()
                let digits = getDigits(this.value)
                digits = digits.slice(0, -1)
                this.value = formatPhone(digits)
            }
        })

        input.addEventListener('focus', function () {
            if (!this.value) {
                this.value = '+7 ('
            }
        })

        input.addEventListener('blur', function () {
            const digits = getDigits(this.value)
            if (digits.length === 0) {
                this.value = ''
            }
        })
    })
}

function initNearestDealer() {
    const btn = document.querySelector('.req-dealer__btn');
    if (!btn) return;

    btn.addEventListener('click', function () {
        if (!navigator.geolocation) {
            alert('Геолокация не поддерживается вашим браузером');
            return;
        }

        // Визуальный фидбек
        const originalContent = btn.innerHTML;
        btn.innerHTML = '<span>Определяем...</span>';
        btn.disabled = true;

        navigator.geolocation.getCurrentPosition(
            function (position) {
                const lat = position.coords.latitude;
                const lon = position.coords.longitude;
                console.log('Координаты пользователя:', lat, lon);

                fetch(`/nearest-dealer/?lat=${lat}&lon=${lon}`)
                    .then(r => r.json())
                    .then(data => {
                        if (data.city) {
                            // Находим radio-кнопку нужного города
                            const radio = document.querySelector(
                                `input[name="city"][data-value="${data.city}"]`
                            );
                            if (radio) {
                                radio.checked = true;
                                // Обновляем отображение текущего города (ваш существующий код)
                                $(".city-select__current").html($(radio).attr("data-value"));
                                $(".city-select").removeClass("_open");
                                radio.dispatchEvent(new Event('change'));
                            }

                            // Активируем карточку дилера и обновляем карту
                            if (data.id) {
                                const $item = $(`.dealer-item[data-dealer-pk="${data.id}"]`);
                                if ($item.length) {
                                    $(".dealer-item").removeClass("_active");
                                    $item.addClass("_active");
                                    $(".dealers__items").addClass("_open");
                                }
                                if (window.DealerMap) {
                                    window.DealerMap.selectByPk(data.id);
                                }

                                // Обновляем select дилера (главная страница)
                                const dealerSelect = document.querySelector('select[name="dealer"]');
                                if (dealerSelect) {
                                    const option = dealerSelect.querySelector(`option[value="${data.id}"]`);
                                    if (option) {
                                        dealerSelect.value = data.id;
                                        dealerSelect.dispatchEvent(new Event('change'));
                                    }
                                }
                            }
                        } else {
                            alert('Ближайший салон не найден');
                        }
                    })
                    .catch(() => alert('Ошибка при поиске салона'))
                    .finally(() => {
                        btn.innerHTML = originalContent;
                        btn.disabled = false;
                    });
            },
            function (err) {
                console.log('Ошибка геолокации:', err.code, err.message);
                btn.innerHTML = originalContent;
                btn.disabled = false;
            },
            { timeout: 10000 }
        );
    });
}

window.addEventListener('DOMContentLoaded', () => {
    fix100vh();
    window.addEventListener('resize', () => {
        fix100vh();
        getScrollBarSize();
    })

    getScrollBarSize();

    // $('input[type="tel"]').mask('+7 (999) 999-99-99', { autoclear: false }, { placeholder: '+7 (   )    -  -  ' });

    document.querySelectorAll('.js-open-modal').forEach(function (btn) {
        btn.addEventListener('click', function (e) {
            e.preventDefault();
            openModal(this.dataset.modal);
        });
    });

    // Формат ввода номера телефона
    initPhoneMask();

    // Форма обратной связи
    initAjaxForm('callbackForm', 'submitBtn', 'thankModal');
    initAjaxForm('testDriveForm', 'testDriveBtnSubmit', 'thankModal');

    initNearestDealer();  // поиск ближайшего дилерского центра
})

function fix100vh() {
    let vh = window.innerHeight * 0.01;
    document.documentElement.style.setProperty('--vh', `${vh}px`);
}

function updatePageNavHeight() {
    var nav = document.querySelector('.page-nav');
    var h = nav ? nav.offsetHeight : 0;
    document.documentElement.style.setProperty('--page-nav-h', h + 'px');
}
updatePageNavHeight();
window.addEventListener('resize', updatePageNavHeight);

// Подсветка активного пункта подменю по видимости секции на экране
(function () {
    const navLinks = document.querySelectorAll('.page-nav__link');
    if (!navLinks.length) return;

    const sectionMap = new Map();
    navLinks.forEach(link => {
        const url = new URL(link.href, location.href);
        const id = url.hash.slice(1);
        if (id) {
            const section = document.getElementById(id);
            if (section) sectionMap.set(section, link);
        }
    });

    if (!sectionMap.size) return;

    const setActive = (link) => {
        navLinks.forEach(l => l.classList.remove('_active'));
        if (link) link.classList.add('_active');
    };

    const navHeight = document.querySelector('.page-nav') ? document.querySelector('.page-nav').offsetHeight : 46;

    const observer = new IntersectionObserver((entries) => {
        entries.forEach(entry => {
            if (entry.isIntersecting) {
                setActive(sectionMap.get(entry.target));
            }
        });
    }, {
        rootMargin: `-${navHeight}px 0px -55% 0px`,
        threshold: 0
    });

    sectionMap.forEach((link, section) => observer.observe(section));
})();

